function fig = cc_pll_data_viewer(input)
% Generated by GitHub Copilot under Lance Lascari's direction.
% Browse a saved PLL single run or sweep without rerunning its analysis.
% cc_pll_data_viewer(), cc_pll_data_viewer(filename), or cc_pll_data_viewer(pll_data_s).
if nargin==0
    [name,directory]=uigetfile('*_data.mat','Open saved PLL dataset');
    if isequal(name,0)
        fig=[];
        return;
    end
    input=fullfile(directory,name);
end
if ischar(input)
    saved=load(input,'pll_data_s');
    if ~isfield(saved,'pll_data_s')
        error('Selected file does not contain pll_data_s');
    end
    data=saved.pll_data_s;
else
    data=input;
end
validate_data(data);
views={'Phase noise surface','Phase noise contours','Individual noise / overlays', ...
    'Noise at selected offsets','Integrated noise (rad RMS)','Estimated EVM (%)', ...
    'Estimated EVM (dB)','Residual FM (unverified method)', ...
    'Achieved bandwidth (Hz)','Achieved phase margin (deg)', ...
    'Capacitors (F)','Resistors (ohm)','Settling estimates (s)', ...
    'Small-signal transient surface','Small-signal transient contours', ...
    'Nonlinear transient surface','Nonlinear transient contours', ...
    'Individual transient / overlays','Nonlinear PFD phase error','Cycle slips'};
labels=cell(1,numel(data.values));
for k=1:numel(labels)
    labels{k}=sprintf('%d: %s = %.9g [%s]',k,data.parameter,data.values(k),data.cases{k}.status);
end
fig=figure('name','PLL data viewer','numbertitle','off','menubar','none', ...
    'position',[80 80 1150 780],'tag','pll_data_viewer');
view_control=uicontrol(fig,'style','popupmenu','units','normalized', ...
    'position',[.32 .925 .66 .055],'string',views,'callback',@redraw,'tag','pll_view_kind');
uicontrol(fig,'style','text','units','normalized','position',[.02 .93 .28 .045], ...
    'string','Select points (Ctrl for overlays)','horizontalalignment','left');
point_control=uicontrol(fig,'style','listbox','units','normalized', ...
    'position',[.02 .66 .28 .27],'string',labels,'max',numel(labels)+1,'min',0, ...
    'value',1,'callback',@redraw,'tag','pll_view_points');
detail_control=uicontrol(fig,'style','edit','units','normalized', ...
    'position',[.02 .065 .28 .57],'max',2,'min',0,'enable','inactive', ...
    'horizontalalignment','left','tag','pll_view_details');
plot_axes=axes('parent',fig,'units','normalized','position',[.38 .17 .57 .69], ...
    'tag','pll_view_axes');
status_control=uicontrol(fig,'style','text','units','normalized', ...
    'position',[.32 .025 .66 .07],'horizontalalignment','left','tag','pll_view_status');
guidata(fig,data);
redraw([],[]);

    function redraw(src,event)
        selection=get(point_control,'value');
        if isempty(selection)
            selection=1;
            set(point_control,'value',selection);
        end
        set(detail_control,'string',point_details(data.cases{selection(1)},data));
        cla(plot_axes,'reset');
        colorbar(plot_axes,'off');
        view(plot_axes,2);
        set(plot_axes,'xscale','linear','yscale','linear','zscale','linear');
        hold(plot_axes,'off');
        mode=get(view_control,'value');
        set(status_control,'string','Surface/summary views include all completed points. Details show the first selected point.');
        try
            if any(mode==[1 2])
                noise_surface(mode==2);
            elseif mode==3
                individual_noise(selection);
            elseif mode==4
                offsets_plot();
            elseif mode>=5 && mode<=10
                fields={'integrated_noise_rad','EVM_percent','EVM_dB','residual_FM_Hz','BW_actual_Hz','PM_actual_deg'};
                metric_plot(fields{mode-4},views{mode});
            elseif mode==11 || mode==12
                component_plot(mode==11);
            elseif mode==13
                settling_plot();
            elseif mode>=14 && mode<=17
                kind='small_signal';
                if mode>=16
                    kind='nonlinear';
                end
                transient_surface(kind,mode==15 || mode==17);
            elseif mode==18 || mode==19
                individual_transient(selection,mode==19);
            else
                slips_plot();
            end
            grid(plot_axes,'on');
            title(plot_axes,views{mode},'interpreter','none');
            drawnow;
        catch err
            warning('PLL viewer plot failed: %s',err.message);
            set(status_control,'string',['Plot failed: ' err.message]);
            errordlg(err.message,'PLL data viewer');
        end
    end

    function [indices,values]=completed_points()
        indices=find(data.completed);
        [values,order]=sort(data.values(indices));
        indices=indices(order);
    end

    function noise_surface(contours)
        [indices,values]=completed_points();
        if isempty(indices)
            no_data('No completed noise analysis; select a failed point to inspect its error.');
            return;
        end
        if numel(indices)==1
            individual_noise(indices);
            set(status_control,'string','Only one completed point: showing a curve instead of a surface.');
            return;
        end
        f=data.cases{indices(1)}.pn_struct.f;
        z=zeros(numel(indices),numel(f));
        for j=1:numel(indices)
            p=data.cases{indices(j)}.pn_struct;
            z(j,:)=interp1(log10(p.f),p.n,log10(f));
        end
        surface_plot(f,values,z,'Offset frequency (Hz)','Phase noise (dBc/Hz)',contours,true);
    end

    function surface_plot(x,y,z,xlabel_text,zlabel_text,contours,log_x)
        if contours
            contour3(plot_axes,x,y,z,20);
        else
            surf(plot_axes,x,y,z,'edgecolor','none');
        end
        view(plot_axes,3);
        if log_x
            set(plot_axes,'xscale','log');
        end
        xlabel(plot_axes,xlabel_text);
        ylabel(plot_axes,strrep(data.parameter,'_',' '));
        zlabel(plot_axes,zlabel_text);
        colorbar(plot_axes);
    end

    function individual_noise(selection)
        legend_names={};
        hold(plot_axes,'on');
        for index=selection(:).'
            c=data.cases{index};
            if ~data.completed(index)
                continue;
            end
            semilogx(plot_axes,c.pn_struct.f,c.pn_struct.n,'linewidth',1.5);
            legend_names{end+1}=sprintf('%s = %g',data.parameter,data.values(index));
            if numel(selection)==1
                semilogx(plot_axes,c.pn_struct.f,c.contributors_dBc_Hz);
                legend_names=[legend_names c.contributor_names];
            end
        end
        set(plot_axes,'xscale','log');
        xlabel(plot_axes,'Offset frequency (Hz)');
        ylabel(plot_axes,'Phase noise (dBc/Hz)');
        ylim(plot_axes,data.config_s.pll_inputs_s.pn_ylimits);
        if isempty(legend_names)
            no_data('Selected points failed; their errors are shown in the details.');
        else
            legend(plot_axes,legend_names,'interpreter','none','location','northeast');
        end
    end

    function offsets_plot()
        [indices,values]=completed_points();
        if isempty(indices)
            no_data('No completed noise results.');
            return;
        end
        z=zeros(numel(indices),numel(data.config_s.run_options_s.noise_offsets_Hz));
        for j=1:numel(indices)
            z(j,:)=data.cases{indices(j)}.noise_at_offsets_dBc_Hz;
        end
        plot(plot_axes,values,z,'-o');
        xlabel(plot_axes,strrep(data.parameter,'_',' '));
        ylabel(plot_axes,'Phase noise (dBc/Hz)');
        names=arrayfun(@(f) sprintf('%g Hz offset',f), ...
            data.config_s.run_options_s.noise_offsets_Hz,'uniformoutput',false);
        legend(plot_axes,names,'interpreter','none','location','northeast');
    end

    function metric_plot(field,label)
        [indices,values]=completed_points();
        z=NaN(size(values));
        for j=1:numel(indices)
            z(j)=data.cases{indices(j)}.(field);
        end
        plot(plot_axes,values,z,'-o');
        xlabel(plot_axes,strrep(data.parameter,'_',' '));
        ylabel(plot_axes,label);
        if any(strcmp(field,{'BW_actual_Hz','PM_actual_deg'})) && ~isempty(indices)
            requested_field='BW_desired_Hz';
            if strcmp(field,'PM_actual_deg')
                requested_field='PM_desired_deg';
            end
            requested=zeros(size(values));
            for j=1:numel(indices)
                requested(j)=data.cases{indices(j)}.requested_inputs.(requested_field);
            end
            hold(plot_axes,'on');
            plot(plot_axes,values,requested,'--');
            legend(plot_axes,{'Achieved','Requested'},'location','northeast');
        end
        if isempty(indices)
            no_data('No completed results for this metric.');
        elseif strcmp(field,'residual_FM_Hz')
            set(status_control,'string','Residual FM retains the existing author warning: method is unverified/flaky.');
        end
    end

    function component_plot(capacitors)
        names={'R2','R3'};
        units='Resistance (ohm)';
        if capacitors
            names={'C1','C2','C3'};
            units='Capacitance (F)';
        end
        [indices,values]=completed_points();
        z=NaN(numel(indices),numel(names));
        for j=1:numel(indices)
            for n=1:numel(names)
                z(j,n)=data.cases{indices(j)}.components.(names{n});
            end
        end
        plot(plot_axes,values,z,'-o');
        xlabel(plot_axes,strrep(data.parameter,'_',' '));
        ylabel(plot_axes,units);
        legend(plot_axes,names,'location','northeast');
    end

    function settling_plot()
        [indices,values]=completed_points();
        z=NaN(numel(indices),2);
        for j=1:numel(indices)
            c=data.cases{indices(j)};
            z(j,:)=[c.small_signal.settling_time_s c.nonlinear.settling_time_s];
        end
        plot(plot_axes,values,z,'-o');
        xlabel(plot_axes,strrep(data.parameter,'_',' '));
        ylabel(plot_axes,'Estimated settling time (s)');
        legend(plot_axes,{'Small-signal','Nonlinear'},'location','northeast');
        set(status_control,'string','Missing markers mean disabled/not settled, not zero. Select a point for status and step/tolerance settings.');
    end

    function transient_surface(kind,contours)
        [indices,values]=completed_points();
        keep=false(size(indices));
        for j=1:numel(indices)
            keep(j)=isfield(data.cases{indices(j)}.(kind),'time_s');
        end
        indices=indices(keep);
        values=values(keep);
        if numel(indices)<2
            if numel(indices)==1
                individual_transient(indices,false);
                set(status_control,'string','Only one transient point: showing time-domain curves instead of a surface.');
            else
                no_data('This transient model was disabled or no completed transient data is available.');
            end
            return;
        end
        end_time=Inf;
        count=2;
        for j=1:numel(indices)
            t=data.cases{indices(j)}.(kind).time_s;
            end_time=min(end_time,t(end));
            count=max(count,min(1000,numel(t)));
        end
        time=linspace(0,end_time,count);
        z=zeros(numel(indices),numel(time));
        for j=1:numel(indices)
            t=data.cases{indices(j)}.(kind);
            z(j,:)=interp1(t.time_s,t.frequency_error_Hz,time);
        end
        surface_plot(time*1e3,values,z,'Time (ms)','Frequency error (Hz)',contours,false);
        set(status_control,'string','Signed frequency error; display resampled to <=1000 times over the common span. Full traces remain stored.');
    end

    function individual_transient(selection,phase)
        names={};
        hold(plot_axes,'on');
        for index=selection(:).'
            if ~data.completed(index)
                continue;
            end
            c=data.cases{index};
            for kind={'small_signal','nonlinear'}
                t=c.(kind{1});
                if ~isfield(t,'time_s') || phase && ~strcmp(kind{1},'nonlinear')
                    continue;
                end
                z=t.frequency_error_Hz;
                if phase
                    z=t.phase_error_cycles;
                end
                plot(plot_axes,t.time_s*1e3,z);
                names{end+1}=sprintf('%s = %g: %s',data.parameter,data.values(index),kind{1});
            end
        end
        xlabel(plot_axes,'Time (ms)');
        ylabel(plot_axes,'Frequency error (Hz)');
        if phase
            ylabel(plot_axes,'Phase error at PFD (cycles)');
        end
        if isempty(names)
            no_data('No enabled transient data for the selected points.');
        else
            legend(plot_axes,names,'interpreter','none','location','northeast');
        end
    end

    function slips_plot()
        [indices,values]=completed_points();
        z=NaN(size(values));
        for j=1:numel(indices)
            if isfield(data.cases{indices(j)}.nonlinear,'cycle_slips')
                z(j)=data.cases{indices(j)}.nonlinear.cycle_slips;
            end
        end
        plot(plot_axes,values,z,'-o');
        xlabel(plot_axes,strrep(data.parameter,'_',' '));
        ylabel(plot_axes,'Nonlinear cycle slips');
        set(status_control,'string','Missing markers mean nonlinear analysis was disabled or unavailable.');
    end

    function no_data(message)
        text(plot_axes,.05,.5,message,'units','normalized','interpreter','none');
        set(status_control,'string',message);
    end
end

function validate_data(data)
if ~isstruct(data) || ~isscalar(data) || ...
        ~all(isfield(data,{'format_version','values','parameter','cases','completed','config_s'})) || ...
        data.format_version~=1
    error('Unsupported or incomplete PLL dataset (expected format_version 1)');
end
validateattributes(data.values,{'numeric'},{'vector','real','finite','nonempty'});
if ~iscell(data.cases) || numel(data.cases)~=numel(data.values) || ...
        numel(data.completed)~=numel(data.values) || ~ischar(data.parameter)
    error('PLL dataset point counts/parameter are invalid');
end
for k=1:numel(data.cases)
    c=data.cases{k};
    if ~isstruct(c) || ~all(isfield(c,{'requested_inputs','status','message'}))
        error('PLL point %d is incomplete',k);
    end
    if data.completed(k) && ~all(isfield(c,{'pn_struct','components','small_signal','nonlinear', ...
            'BW_actual_Hz','PM_actual_deg','integrated_noise_rad','EVM_percent','EVM_dB', ...
            'residual_FM_Hz','noise_at_offsets_dBc_Hz','contributors_dBc_Hz','contributor_names'}))
        error('Completed PLL point %d lacks analysis data',k);
    end
end
end

function lines=point_details(c,data)
lines={['Status: ' c.status]};
if ~isempty(c.message)
    lines{end+1}=['Message: ' c.message];
end
if strcmp(c.status,'complete')
    lines=[lines {sprintf('Achieved BW: %.9g Hz',c.BW_actual_Hz), ...
        sprintf('Achieved PM: %.9g deg',c.PM_actual_deg), ...
        sprintf('Effective Kvco: %.9g Hz/V',c.Kvco_Hz_volt), ...
        sprintf('VCO target: %.9g Hz',c.Fvco_Hz), ...
        sprintf('RMS phase: %.9g rad',c.integrated_noise_rad), ...
        sprintf('EVM: %.9g %% / %.9g dB',c.EVM_percent,c.EVM_dB), ...
        sprintf('Residual FM (unverified): %.9g Hz',c.residual_FM_Hz), ...
        sprintf('Small-signal: %s, %.9g s',c.small_signal.status,c.small_signal.settling_time_s), ...
        sprintf('Nonlinear: %s, %.9g s',c.nonlinear.status,c.nonlinear.settling_time_s), ...
        '', 'Actual components:'}];
    lines=[lines struct_lines(c.components)];
    lines=[lines {'' 'Noise at selected offsets:'}];
    for j=1:numel(c.noise_offsets_Hz)
        lines{end+1}=sprintf('%.9g Hz: %.9g dBc/Hz',c.noise_offsets_Hz(j),c.noise_at_offsets_dBc_Hz(j));
    end
end
lines=[lines {'' 'Requested inputs:'} struct_lines(c.requested_inputs) ...
    {'' 'Metric / run settings:'} struct_lines(data.config_s.run_options_s)];
end

function lines=struct_lines(s)
names=fieldnames(s);
lines=cell(1,numel(names));
for k=1:numel(names)
    value=s.(names{k});
    if ~ischar(value)
        value=mat2str(value,9);
    end
    lines{k}=[names{k} ' = ' value];
end
end
